function renderAdmin(s,c){if(s==='inicio'){setHeader('Inicio');const u=getCollection('usuarios'),r=getCollection('reportes');c.innerHTML=statCards([['Usuarios',u.length],['Alumnos',u.filter(x=>x.rol==='ALUMNO').length],['Materias',getCollection('materias').length],['Reportes abiertos',r.filter(x=>x.estado!=='RESUELTO').length]])+`<div class="section-head"><h2>Resumen</h2></div><div class="grid"><div class="card"><strong>Roles registrados</strong><p class="muted">ADMIN, ALUMNO, PADRE y MANTENIMIENTO.</p></div><div class="card"><strong>Avisos activos</strong><p class="muted">${getCollection('avisos').length} avisos disponibles.</p></div><div class="card"><strong>Eventos</strong><p class="muted">${getCollection('eventos').length} eventos en calendario.</p></div></div>`}else if(s==='usuarios'){setHeader('Usuarios');const a=getCollection('usuarios');c.innerHTML=`<div class="section-head"><h2>Usuarios</h2><button class="btn primary" onclick="newUser()">+ Crear usuario</button></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>Nombre</th><th>Correo</th><th>Rol</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${a.map(u=>`<tr><td>${escapeHTML(u.nombre)}</td><td>${escapeHTML(u.email)}</td><td>${u.rol}</td><td><span class="badge">${u.activo?'ACTIVO':'INACTIVO'}</span></td><td><button class="btn secondary" onclick="toggleUser('${u.id}')">${u.activo?'Desactivar':'Activar'}</button></td></tr>`).join('')}</tbody></table></div>`}else if(s==='materias'){setHeader('Materias');c.innerHTML=`<div class="section-head"><h2>Materias</h2><button class="btn primary" onclick="newSubject()">+ Agregar materia</button></div><div class="grid">${getCollection('materias').map(m=>`<div class="card subject"><strong>${escapeHTML(m.nombre)}</strong><small>${escapeHTML(m.docente)}</small><small>Grupo: ${escapeHTML(m.grupo)}</small></div>`).join('')}</div>`}else if(s==='avisos'){setHeader('Avisos');c.innerHTML=`<div class="section-head"><h2>Avisos</h2><button class="btn primary" onclick="newNotice()">+ Nuevo aviso</button></div><div class="card">${getCollection('avisos').map(a=>`<div class="notice-row"><div><strong>${escapeHTML(a.titulo)}</strong><small class="muted">${escapeHTML(a.texto)}</small></div><small>${a.fecha}</small></div>`).join('')}</div>`}else if(s==='reportes'){setHeader('Reportes');c.innerHTML=`<div class="section-head"><h2>Reportes de mantenimiento</h2></div><div class="card">${getCollection('reportes').map(reportRow).join('')}</div>`}}
function newUser(){modal('Crear usuario',`<form><div class="form-grid"><label>Nombre<input name="nombre" required></label><label>Correo<input name="email" type="email" required></label><label>Contraseña<input name="password" value="123456" required></label><label>Rol<select name="rol"><option>ADMIN</option><option>ALUMNO</option><option>PADRE</option><option>MANTENIMIENTO</option></select></label></div><div class="actions"><button class="btn primary">Crear</button></div></form>`,f=>{const a=getCollection('usuarios');a.push({id:uid('u'),nombre:f.get('nombre'),email:f.get('email'),password:f.get('password'),rol:f.get('rol'),activo:true});saveCollection('usuarios',a);document.getElementById('modalRoot').innerHTML='';render('usuarios');showToast('Usuario creado')})}
function toggleUser(id){const a=getCollection('usuarios'),u=a.find(x=>x.id===id);if(u&&u.id!==user.id)u.activo=!u.activo;saveCollection('usuarios',a);render('usuarios')}
function newSubject(){modal('Nueva materia',`<form><div class="form-grid"><label>Nombre<input name="nombre" required></label><label>Grupo<input name="grupo" value="3°A" required></label><label class="wide">Docente<input name="docente"></label></div><div class="actions"><button class="btn primary">Guardar</button></div></form>`,f=>{const a=getCollection('materias');a.push({id:uid('m'),nombre:f.get('nombre'),grupo:f.get('grupo'),docente:f.get('docente')});saveCollection('materias',a);document.getElementById('modalRoot').innerHTML='';render('materias');showToast('Materia agregada')})}
function newNotice(){modal('Nuevo aviso',`<form><div class="form-grid"><label class="wide">Título<input name="titulo" required></label><label class="wide">Texto<textarea name="texto" required></textarea></label><label>Fecha<input name="fecha" type="date" required></label></div><div class="actions"><button class="btn primary">Publicar</button></div></form>`,f=>{const a=getCollection('avisos');a.push({id:uid('av'),titulo:f.get('titulo'),texto:f.get('texto'),fecha:f.get('fecha')});saveCollection('avisos',a);document.getElementById('modalRoot').innerHTML='';render('avisos');showToast('Aviso publicado')})}